//! A fake plugin that really gets dlopen'ed, used by `pmpx`'s end-to-end tests -- it makes
//! the whole "detect -> resolve -> `dlopen` -> cross-ABI call to `command()` -> spawn" chain
//! run for real.
//!
//! It deliberately leaves a few traps to verify the host's fault tolerance: `Exec` returns
//! [`PluginError::unsupported_verb`] (the host must degrade to passing through verbatim for
//! `exec`), `Remove` panics outright (the host must stay alive and get `PMPX_ERR_INTERNAL`),
//! and the remaining verbs return a command that really runs.

use std::ffi::OsString;

use pmpx_plugin::{CommandSpec, Context, Family, PackageManager, PluginError, Verb};

struct FakePm;

impl PackageManager for FakePm {
    fn name(&self) -> &str {
        // Must match `plugin.name` in the manifest, otherwise the host refuses to load it.
        "fakepm"
    }

    fn family(&self) -> Family {
        Family::new("faketest")
    }

    fn command(
        &self,
        ctx: &Context,
        verb: Verb,
        args: &[OsString],
    ) -> Result<CommandSpec, PluginError> {
        // The end-to-end proof that a plugin's own logging reaches the host: pmpx adds the id, and
        // only prints it when a trace was asked for.
        pmpx_plugin::debug!("mapping {verb} with {} matched file(s)", ctx.matched.len());

        match verb {
            // A command that is guaranteed to succeed and echo back: the tests assert with it
            // that the root / matched / args crossing the boundary are correct.
            Verb::Install | Verb::Build | Verb::Test | Verb::Run | Verb::Update => {
                let probe = format!(
                    "pmpx-probe root={} matched={} verb={} args={}",
                    ctx.project_root.display(),
                    ctx.matched.join("|"),
                    verb,
                    args.iter()
                        .map(|a| a.to_string_lossy().into_owned())
                        .collect::<Vec<_>>()
                        .join(",")
                );

                // `echo` exists on both platforms, but on Windows it has to be the cmd builtin
                #[cfg(windows)]
                let spec = CommandSpec::new("cmd").arg("/c").arg("echo").arg(probe);
                #[cfg(not(windows))]
                let spec = CommandSpec::new("echo").arg(probe);

                Ok(spec)
            }

            // Explicitly declared unsupported, so the host has to pass through verbatim itself
            Verb::Exec => Err(PluginError::unsupported_verb(verb)),

            // Verifies the panic fallback. It must never cross `extern "C"`.
            Verb::Remove => panic!("the fake plugin deliberately blows up on remove"),

            // Verb is a closed enum, so this is unreachable in theory; it is kept so that
            // adding a verb later cannot silently slip through
            #[allow(unreachable_patterns)]
            other => Err(PluginError::other(format!("{other} is not implemented"))),
        }
    }
}

/// The factory function. The wrapper generated by crate-plugin-kit calls this too.
pub fn create() -> Box<dyn PackageManager> {
    Box::new(FakePm)
}

pmpx_plugin::export!(create);
